package module02.examples;

/**
 * Demonstrates compile-time constant inlining with final static.
 */
public class ConstantFolding {
    
    // Compile-time constants
    public static final int BASE = 10;
    public static final int MULTIPLIER = 5;
    
    public static void main(String[] args) {
        // Constant Folding:
        // The compiler evaluates BASE * MULTIPLIER at compile time.
        // The generated bytecode directly loads '50' into 'result'.
        // It does NOT perform the multiplication at runtime.
        int result = BASE * MULTIPLIER;
        
        System.out.println("Constant folded result: " + result);
        
        // Also works with local final variables
        final int a = 20;
        final int b = 30;
        int localResult = a + b; // Compiler replaces with 50
        
        System.out.println("Local constant folded result: " + localResult);
    }
}
